import { Component, OnInit, ErrorHandler, NgZone } from "@angular/core";
import { environment as env } from "../../environments/environment";
import { interval, Subscription, Observable, Subject } from "rxjs";
import {
  HttpEventType,
  HttpEvent,
  HttpErrorResponse,
} from "@angular/common/http";
import { GetconfigService } from "../services/getconfig/getconfig.service";
import { WebsocketService } from "../services/websocket/websocket.service";
import { WebsocketMonitorService } from "../services/websocketMonitor/websocket-monitor.service";

import { TblConfig } from "../classes/tbl-config";
import * as Highcharts from "highcharts";
import {
  FormGroup,
  FormControl,
  Validators,
  FormBuilder,
} from "@angular/forms";
import { SubmitRespon } from "../classes/submit-respon";
import { NgxSpinnerService } from "ngx-spinner";

import * as moment from "moment";

declare var require: any;

let Boost = require("highcharts/modules/boost");
let noData = require("highcharts/modules/no-data-to-display");
let More = require("highcharts/highcharts-more");

Boost(Highcharts);
noData(Highcharts);
More(Highcharts);
noData(Highcharts);

@Component({
  selector: "app-home",
  templateUrl: "./home.component.html",
  styleUrls: ["./home.component.scss"],
})
export class HomeComponent implements OnInit {
  public options: any;
  public chart: any;

  dataEvent: Subject<any> = new Subject<any>();
  redrawEvent: Subject<any> = new Subject<any>();

  ip: string;
  port: number;
  serverStat: string = "connect_error";
  listen_node: string;
  sensor_config: any;

  //COUNT VARIABLE
  eventCount: number;
  eventUploadedCount: number;
  samplingCount: number;
  totalCount: number;
  version: string;

  nodeNameForm: FormGroup;

  private subscriptions: Subscription[] = [];
  private subscriptionsServer: Subscription[] = [];

  ngOnDestroy() {
    this.subscriptions.forEach((subscriptions) => subscriptions.unsubscribe());
    this.subscriptionsServer.forEach((subscriptions) =>
      subscriptions.unsubscribe()
    );
  }

  constructor(
    private zone: NgZone,
    private _getConf: GetconfigService,
    private _webSockServ: WebsocketService,
    private _monitorSocket: WebsocketMonitorService,
    private _formBuilder: FormBuilder,
    private spinner: NgxSpinnerService
  ) {
    this.version = env.version;

    this.nodeNameForm = this._formBuilder.group({
      node_name: ["", Validators.compose([Validators.required])],
      ctrlport: ["", Validators.compose([Validators.required])],
      ctrlip: ["", Validators.compose([Validators.required])],
    });
  }

  showChangeNodeNameDialog: boolean = false;

  changeNodeName() {
    this.showChangeNodeNameDialog = true;
  }

  changeNodeNameSubmit = new SubmitRespon();

  submitChangeNodeNameForm() {
    if (!this.nodeNameForm.valid || this.changeNodeNameSubmit.load)
      return false;
    this.changeNodeNameSubmit.reset();
    this.changeNodeNameSubmit.load = true;

    this.spinner.show();

    let value = this.nodeNameForm.value;

    this._getConf
      .updateSensorName(this.localhost, this.localhostPort, value)
      .subscribe(
        (event: HttpEvent<any>) => {
          if (event.type === HttpEventType.Response) {
            if (event.status == 200) {
              let body = event.body;
              let error = body.error;
              let msg = body.message;

              if (!error) {
                this.spinner.show();
                //alert("SUCCESSFULY CHANGE NODE NAME");
                location.reload();
              } else {
                alert(msg);
                location.reload();
                // this.queueTbl.tblVal = [];
                // //this.queueTbl.listVal = this.queueTbl.listVal.slice();
                // this.queueTbl.listTotal = 0;
              }

              this.changeNodeNameSubmit.load = false;
            } else {
              alert(event.status);
            }

            this.spinner.hide();
          }
        },
        (err: HttpErrorResponse) => {
          console.log(err);
          //this.alertError(err.message);
        }
      );
  }

  ngOnInit() {}

  ngAfterViewInit() {
    this.zone.runOutsideAngular(() => {
      this.options = {
        boost: {
          enabled: true,
          useGPUTranslations: true,
          usePreallocated: true,
          allowForce: true,
          seriesThreshold: 1,
        },

        colors: [
          "red",
          "green",
          "blue",
          "#DDDF00",
          "#24CBE5",
          "#64E572",
          "#FF9655",
          "#FFF263",
          "#6AF9C4",
        ],

        chart: {
          type: "spline",
          //   backgroundColor: {
          //  		linearGradient: [0, 0, 500, 500],
          // stops: [
          //  			[0, 'rgb(255, 255, 255)'],
          //  			[1, 'rgb(240, 240, 255)']
          // ]
          //  	},
        },

        legend: {
          itemStyle: {
            font: "9pt Trebuchet MS, Verdana, sans-serif",
            color: "black",
          },
          itemHoverStyle: {
            color: "gray",
          },
          enabled: true,
        },

        title: {
          style: {
            color: "#000",
            font: 'bold 16px "Trebuchet MS", Verdana, sans-serif',
          },
          text: "",
        },

        subtitle: {
          style: {
            color: "#666666",
            font: 'bold 12px "Trebuchet MS", Verdana, sans-serif',
          },
          enabled: false,
        },

        plotOptions: {
          series: {
            boostThreshold: 1,
            turboThreshold: 1,

            marker: {
              enabled: false,
              states: {
                hover: {
                  enabled: true,
                  radius: 3,
                },
              },
            },
          },
        },

        tooltip: {
          // formatter: function () {
          //   var point = this.points[0];
          //   console.log(point);
          //   return '<b>' + point + '</b><br/>' + Highcharts.dateFormat('%A %B %e %Y', this.x) + ':<br/>' +
          //     '1 USD = ' + Highcharts.numberFormat(point.y, 2) + ' EUR';
          // },
          // shared: true
          //valueSuffix: ' m/s'
        },

        // tooltip: {
        //     //valueDecimals: 2
        //     dateTimeLabelFormats: {
        //     	millisecond: "%A, %b %e, %H:%M:%S.%L."
        //     }

        // },

        xAxis: {
          //minTickInterval: moment.duration(1, 'month').asMilliseconds(),
          type: "category",
          labels: {
            enabled: false,
            rotation: -60,

            formatter: function () {
              //console.log(this.value);

              return moment(this.value).format("h:mm:ss");

              return Highcharts.dateFormat("%h:%M:%S", this.value);
            },
          },
        },

        yAxis: {
          title: {
            text: null,
          },
          // max: 2,
          // min: -2
          // maxZoom: 0.1
        },

        series: [
          {
            name: "X AXIS",
            data: [],
          },
          {
            name: "Y AXIS",
            data: [],
          },
          {
            name: "Z AXIS",
            data: [],
          },
        ],
      };

      this.chart = Highcharts.chart("container", this.options);

      // FIX WIDTH SIZE OF HIGHCHART
      const source = interval(1000);

      let counter = 0;
      //output: 0,1,2,3,4,5....
      const subscribe = source.subscribe((val) => {
        this.chart.reflow();

        counter++;

        if (counter == 5) {
          subscribe.unsubscribe();
        }
      });
    });

    this._monitorSocket.setUrl(this.localhost, this.localhostPort);

    this._monitorSocket.socketStat().subscribe((data: any) => {
      this.serverStatModule = data;

      if (this.serverStatModule == "connected") {
        this.getSensorConfig();
      } else {
        this.subscriptionsServer.forEach((subscriptions) =>
          subscriptions.unsubscribe()
        );
        this.subscriptions.forEach((subscriptions) =>
          subscriptions.unsubscribe()
        );
      }
    });
  }

  serverStatModule: string = "connect_error";

  localhost: string = "localhost";
  localhostPort: number = 3333;

  getSensorConfig() {
    this._getConf.getSensorConfig(this.localhost, this.localhostPort).subscribe(
      (event: HttpEvent<any>) => {
        if (event.type === HttpEventType.Response) {
          if (event.status == 200) {
            let body = event.body;
            let error = body.error;
            let msg = body.message;

            if (!error) {
              this.sensor_config = body.data;

              this.ip = this.sensor_config["ctrlip"];
              this.port = this.sensor_config["ctrlport"];
              this.listen_node = this.sensor_config["node_name"];

              this.nodeNameForm.controls["node_name"].setValue(
                body.data["node_name"]
              );
              this.nodeNameForm.controls["ctrlip"].setValue(
                body.data["ctrlip"]
              );
              this.nodeNameForm.controls["ctrlport"].setValue(
                body.data["ctrlport"]
              );

              this.startGraph();
            } else {
              alert(msg);
            }
          } else {
            alert(event.status);
          }
        }
      },
      (err: HttpErrorResponse) => {
        console.log(err);
        //this.alertError(err.message);
      }
    );
  }

  listen() {
    this.subscriptions.push(
      this._webSockServ
        .listen(this.listen_node + "-light")
        .subscribe((data: any) => {
          this._monitorSocket.emit("light", [
            data,
            this.listen_node,
            "monitor",
          ]);
        })
    );

    this.subscriptions.push(
      this._webSockServ
        .listen(this.listen_node + "-announcement")
        .subscribe((data: any) => {
          this._monitorSocket.emit("announcement", [
            data,
            this.listen_node,
            "monitor",
          ]);
        })
    );

    this.subscriptions.push(
      this._webSockServ.listen(this.listen_node).subscribe((data: any) => {
        let xData = [];
        let yData = [];
        let zData = [];

        let dataArray = JSON.parse(data);

        //console.log(Math.random());

        this.startDataInterval(dataArray);
      })
    );
  }

  startGraph() {
    this._webSockServ.setUrl(this.ip, this.port);

    this.subscriptionsServer.push(
      this._webSockServ.socketStat().subscribe((data: any) => {
        console.log(data);
        this.serverStat = data;

        if (this.serverStat == "connected") {
          this._monitorSocket.emit("close_gpio", ["close_gpio"]);

          // setTimeout(() => {

          // this._webSockServ.emit("light", ["green", "usher01"]);
          // }, 5000);

          this.listen();
        } else {
          this.subscriptions.forEach((subscriptions) =>
            subscriptions.unsubscribe()
          );
        }
      })
    );
  }

  timestamp: any;
  xValue: any;
  yValue: any;
  zValue: any;
  backToNormalsec: number = 20;

  intensity: number;

  startDataInterval(res) {
    let resLen = res.length;

    let timestamp = 0;
    let xval = 0;
    let yval = 0;
    let zval = 0;

    let intensity = 0;

    for (var x = 0; x < resLen; x++) {
      timestamp = parseInt(res[x][1]);
      xval = parseFloat(res[x][2]);
      yval = parseFloat(res[x][3]);
      zval = parseFloat(res[x][4]);
      //intent   	= parseInt(res[x][5]);

      let intentIndex = parseInt(res[x][5]);

      // GET MAXIMUM INTENSITY ON FILE
      if (intentIndex > intensity) {
        intensity = intentIndex;
      }

      var series = this.chart.series[0],
        shift = series.data.length > 500; // shift if the series is
      //	this.chart.xAxis[0].addCategories(timestamp, false, shift);
      // this.chart.series[0].addPoint([timestamp, xval], false, shift);
      //this.chart.series[1].addPoint([timestamp, yval], false, shift);
      //this.chart.series[2].addPoint([timestamp, zval], false, shift);

      this.chart.series[0].addPoint(xval, false, shift);
      this.chart.series[1].addPoint(yval, false, shift);
      this.chart.series[2].addPoint(zval, false, shift);
      //this.chart.series[1].addPoint([timestamp, yval], false, shift);
      //this.chart.series[2].addPoint([timestamp, zval], false, shift);

      //this.dataEvent.next(data);
    }

    this.chart.redraw();

    if (this.intensity) {
      //peis
      if (intensity < this.intensity && this.backToNormalsec > 0) {
        this.backToNormalsec--;
      } else {
        this.intensity = intensity;
        this.backToNormalsec = 20;
      }
    } else {
      this.intensity = intensity;
    }

    //this.redrawEvent.next(true);

    // this.chart.xAxis[0].setCategories(this.timeData);
    // this.chart.series[0].setData(this.xData, true, false);
    // this.chart.series[1].setData(this.yData, true, false);
    // this.chart.series[2].setData(this.zData, true, false);

    this.timestamp = timestamp;
    this.xValue = xval;
    this.yValue = yval;
    this.zValue = zval;
    //this.intensity = intent;
  }

  intenBgColor(intensity) {
    let className = "";

    switch (intensity) {
      case 1:
        className = "inten-1";
        break;
      case 2:
        className = "inten-2";
        break;
      case 3:
        className = "inten-2";
        break;
      case 4:
        className = "inten-4";

        break;
      case 5:
        className = "inten-5";
        break;
      case 6:
        className = "inten-6";
        break;
      case 7:
        className = "inten-7";
        break;
      case 8:
        className = "inten-8";
        break;
      case 9:
        className = "inten-9";
        break;
      case 10:
        className = "inten-10";
        break;
      default:
        break;
    }

    return className;
  }

  convert(timestamp) {
    return parseInt(timestamp);
  }
}
