import { Injectable } from "@angular/core";
import { HttpClient, HttpRequest, HttpHeaders } from "@angular/common/http";
import { environment as env } from "../../../environments/environment";
import { Observable, throwError, BehaviorSubject } from "rxjs";
import { catchError } from "rxjs/operators";

@Injectable({
  providedIn: "root",
})
export class GetconfigService {
  constructor(private _httpClient: HttpClient) {}

  getConfig(url) {
    return this._httpClient.get(url, {
      observe: "response",
      reportProgress: true,
    });
  }

  getSensorConfig(url, port) {
    console.log("http://" + url + ":" + port + "/getSensorConfig");
    return this._httpClient.get(
      "http://" + url + ":" + port + "/getSensorConfig",
      { observe: "response", reportProgress: true }
    );
  }

  getHistory(url, port) {
    return this._httpClient.get("http://" + url + ":" + port + "/getHistory", {
      observe: "response",
      reportProgress: true,
    });
  }

  getBldgs(url) {
    return this._httpClient.get(url, {
      observe: "response",
      reportProgress: true,
    });
  }

  getAllBldgNodeStatus(url) {
    return this._httpClient.get(url, {
      observe: "response",
      reportProgress: true,
    });
  }

  getWarningBefore(url, port, event_id) {
    let body = new FormData();
    body.append("eventId", event_id);

    return this._httpClient.post(
      "http://" + url + ":" + port + "/getBefore",
      body,
      { observe: "response", reportProgress: true }
    );
  }

  getWarningDuring(url, port, event_id) {
    let body = new FormData();
    body.append("eventId", event_id);

    return this._httpClient.post(
      "http://" + url + ":" + port + "/getDuring",
      body,
      { observe: "response", reportProgress: true }
    );
  }

  getWarningAfter(url, port, event_id) {
    let body = new FormData();
    body.append("eventId", event_id);

    return this._httpClient.post(
      "http://" + url + ":" + port + "/getAfter",
      body,
      { observe: "response", reportProgress: true }
    );
  }

  updateSensorName(url, port, formVal) {
    let body = {
      node_name: formVal.node_name,
      ctrlip: formVal.ctrlip,
      ctrlport: formVal.ctrlport,
    };

    return this._httpClient.post(
      "http://" + url + ":" + port + "/updateSensorName",
      body,
      { observe: "response", reportProgress: true }
    );
  }
}
